import json
import base64
import os
import boto3

s3_client = boto3.client('s3')
BUCKET_NAME = os.environ.get('FIRMWARE_BUCKET', 'iot-device-firmware-updates')
ALLOWED_DEVICE_TYPES = ['sensor-v2', 'actuator-v3', 'gateway-v1']

def lambda_handler(event, context):
    """
    IoT Device Message Handler
    Accepts firmware update packages and diagnostic bundles from field devices.
    Devices authenticate via their embedded certificates and send payloads
    as base64-encoded binary in the request body.
    """
    try:
        body = json.loads(event.get('body', '{}'))
    except (json.JSONDecodeError, TypeError):
        return {'statusCode': 400, 'body': json.dumps({'error': 'Invalid JSON payload'})}

    device_id = body.get('device_id', '')
    device_type = body.get('device_type', '')
    message_type = body.get('message_type', '')
    payload_b64 = body.get('payload', '')
    filename = body.get('filename', '')

    # Validate device type
    if device_type not in ALLOWED_DEVICE_TYPES:
        return {'statusCode': 403, 'body': json.dumps({'error': 'Unknown device type'})}

    # Validate device_id format (alphanumeric + hyphens)
    if not device_id or not all(c.isalnum() or c == '-' for c in device_id):
        return {'statusCode': 400, 'body': json.dumps({'error': 'Invalid device_id format'})}

    # Process based on message type
    if message_type == 'firmware_upload':
        return handle_firmware_upload(device_id, device_type, filename, payload_b64)
    elif message_type == 'diagnostic_bundle':
        return handle_diagnostic_upload(device_id, filename, payload_b64)
    elif message_type == 'telemetry':
        return handle_telemetry(device_id, body.get('readings', {}))
    else:
        return {'statusCode': 400, 'body': json.dumps({'error': 'Unknown message_type'})}


def handle_firmware_upload(device_id, device_type, filename, payload_b64):
    """Store firmware binary uploaded by device for fleet distribution."""
    if not filename:
        return {'statusCode': 400, 'body': json.dumps({'error': 'filename required'})}

    # Decode payload
    try:
        file_bytes = base64.b64decode(payload_b64)
    except Exception:
        return {'statusCode': 400, 'body': json.dumps({'error': 'Invalid base64 payload'})}

    # No file extension or content-type validation - devices send raw binaries
    # The filename is used directly as the S3 key prefix
    s3_key = f"firmware/{device_type}/{device_id}/{filename}"

    s3_client.put_object(
        Bucket=BUCKET_NAME,
        Key=s3_key,
        Body=file_bytes,
        Metadata={'device_id': device_id, 'device_type': device_type}
    )

    return {
        'statusCode': 200,
        'body': json.dumps({'status': 'uploaded', 'key': s3_key})
    }


def handle_diagnostic_upload(device_id, filename, payload_b64):
    """Store diagnostic bundles (logs, core dumps) from devices."""
    if not filename:
        filename = f"{device_id}-diag.tar.gz"

    try:
        file_bytes = base64.b64decode(payload_b64)
    except Exception:
        return {'statusCode': 400, 'body': json.dumps({'error': 'Invalid base64 payload'})}

    # Path traversal possible via filename - no sanitization
    s3_key = f"diagnostics/{device_id}/{filename}"

    s3_client.put_object(
        Bucket=BUCKET_NAME,
        Key=s3_key,
        Body=file_bytes,
        Metadata={'device_id': device_id, 'type': 'diagnostic'}
    )

    return {
        'statusCode': 200,
        'body': json.dumps({'status': 'diagnostic_stored', 'key': s3_key})
    }


def handle_telemetry(device_id, readings):
    """Process telemetry readings (temperature, humidity, etc)."""
    # Just acknowledge - actual processing via EventBridge
    return {
        'statusCode': 200,
        'body': json.dumps({'status': 'telemetry_received', 'device_id': device_id})
    }
